+        } else if (v.getId() == muteButton.getId()) {
+            onMuteUnmuteButtonClicked();
+        } else if (v.getId() == playerCloseButton.getId()) {
+            service.sendBroadcast(new Intent(VideoDetailFragment.ACTION_HIDE_MAIN_PLAYER));
+        }
