+        if (event.getAction() == MotionEvent.ACTION_UP) {
+            if (DEBUG) {
+                Log.d(TAG, "onTouch() ACTION_UP > v = [" + v + "],  "
+                        + "e1.getRaw = [" + event.getRawX() + ", " + event.getRawY() + "]");
